{
  "name": "shop-api",
  "version": "1.4.0",
  "type": "module",
  "scripts": {
    "dev": "node --watch src/server.js",
    "lint": "eslint .",
    "test": "node --test",
    "pretest": "npm run lint",
    "build": "tsc -p tsconfig.build.json",
    "postbuild": "node scripts/copy-assets.js",
    "version:print": "node -e \"console.log(process.env.npm_package_version)\""
  }
}

// npm test                      -> runs pretest (lint) then test
// npm run test -- --test-only   -> passes --test-only to node --test
// npm run version:print         -> 1.4.0
// node --run build              -> faster, but skips prebuild/postbuild

{
  "name": "@ann/slugify",
  "version": "2.0.0",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "require": "./dist/index.cjs"
    },
    "./locales/*": "./dist/locales/*.js",
    "./package.json": "./package.json"
  },
  "imports": {
    "#internal/*": "./src/internal/*.js"
  },
  "main": "./dist/index.cjs",
  "sideEffects": false,
  "files": ["dist"]
}
// import { slugify } from "@ann/slugify"          OK
// import de from "@ann/slugify/locales/de"        OK
// import x from "@ann/slugify/dist/index.js"      ERR_PACKAGE_PATH_NOT_EXPORTED

